from __future__ import absolute_import

import logging
import time

from taf.selenium.gnb.oam.coam.vdu.pages.common_page import CommonPage
from taf.selenium.gnb.oam.coam.vdu.pages.panels.navigation import NavigationPanel
from taf.selenium.gnb.oam.coam.vdu.pages.panels.view import ViewPanel


class Procedures(CommonPage):
    """
    The class corresponding to Procedures page on selenium_coam_vdu web, all operations under Procedures
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"R&D Debug Parameters": RNDDebugParametersStatusPage(driver, version)}
        super(Procedures, self).__init__(driver, version, self._instance_dict)


class RNDDebugParametersStatusPage(object):
    """
    A class will be called by Procedures, all operations of R&D Debug Parameters will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['gavel', 'R&D Debug Parameters Management', 'R&D Debug Parameters']

    def __init__(self, driver, version):
        self._navigation_panel = RNDDebugParametersStatusPageNavigationPanel(driver, version)
        self._view_panel = RNDDebugParametersStatusPageViewPanel(driver, version)

    def set_rnd_debug_parameters(self, object_name, filter_param, new_value, timeout):
        """
        Keyword for setting rnd parameter values or editing existing parameter values of given object name.

        :param object_name: domain object name in which parameter need to set or edit
        :param filter_param: str, parameter name
        :param new_value: str, new value to set. If your editing value in checkbox it has to be passed as a list.
        :param timeout: int, timeout for the element be available to click

        :return: str, set rnd param status info
        """
        return self._view_panel.set_rnd_debug_parameters(object_name, filter_param, new_value, timeout)

    def restore_rnd_debug_parameters(self, object_name, filter_param, timeout):
        """
        Keyword for restoring rnd parameter values of given object name.

        :param object_name: domain object name in which parameter need to set or edit
        :param filter_param: str, parameter name
        :param timeout: int, timeout for the element be available to click

        :return: str, restore rnd param status info
        """
        return self._view_panel.restore_rnd_debug_parameters(object_name, filter_param, timeout)


class RNDDebugParametersStatusPageNavigationPanel(NavigationPanel):
    pass


class RNDDebugParametersStatusPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(RNDDebugParametersStatusPageViewPanel, self).__init__(driver, version)

    def restore_rnd_debug_parameters(self, object_name, filter_param, timeout):
        self.filter_rnb_debug_parameters(object_name=object_name, filter_param=filter_param, timeout=timeout)
        time.sleep(2)
        if self.element_exists(self.locator.DISABLED_RESTORE_BUTTON, timeout=2):
            raise RuntimeError("Restore button is disabled for the element {}.".format(filter_param))
        self.click_enabled_element(self.locator.PARAM_RESTORE_BUTTON, timeout)
        self.click_enabled_element(self.locator.CONFIRM_RESTORE_BUTTON, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(self.locator.RESTORE_BUTTON_STARTED),
                                 timeout=10)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(self.locator.RESTORE_BUTTON_FINISHED),
                                 timeout=10)
        restore_status = self.get_text(self.locator.RESTORE_SUCCESS_BUTTON, timeout)
        if restore_status == 'Success':
            logging.debug('Restore to default value is successful for the element {}.'.format(filter_param))
            return restore_status

    def apply_rnd_debug_parameters(self, filter_param, timeout):
        if self.element_exists(self.locator.CONFIRM_APPLY_CHANGES, timeout=3):
            raise RuntimeError("Apply changes button is disabled for the element {}. "
                               "may be your trying to set the same value please check".format(filter_param))
        self.click_enabled_element(self.locator.APPLY_CHANGES, timeout)
        self.click_enabled_element(self.locator.APPLY_CHANGES_BUTTON_CONFIRM, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(self.locator.APPLY_CHANGES_OPERATION_MESSAGE),
                                 timeout=10)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(self.locator.APPLY_CHANGES_FINISHED_MESSAGE),
                                 timeout=10)
        time.sleep(2)
        apply_status = self.get_text(self.locator.APPLY_CHANGES_SUCCESS, timeout)
        if apply_status == 'Apply Changes success':
            logging.debug('Apply changes is successful for the element {}.'.format(filter_param))
            return apply_status

    def filter_rnb_debug_parameters(self, object_name, filter_param, timeout):
        self.click_enabled_element(self.locator.FILTER_CONTAINER, timeout)
        self.click_enabled_element(self.locator.DEBUG_PARAM_FILTER_INPUT, timeout)
        self.insert_text_to_enable_element(self.locator.DEBUG_PARAM_FILTER_INPUT, object_name, timeout)
        self.click_enabled_element(self.locator.DOMAIN_NAME.format(object_name), timeout)
        time.sleep(2)
        self.insert_text_to_enable_element(self.locator.FILTER_INPUT_TEXT, filter_param, timeout)

    def set_rnd_debug_parameters(self, object_name, filter_param, new_value, timeout):
        """
        Keyword for setting rnd parameter values or editing existing parameter values of given object name.

        :param object_name: domain object name in which parameter need to set or edit
        :param filter_param: str, parameter name
        :param new_value: str, new value to set. If your editing value in checkbox it has to be passed as a list.
        :param timeout: int, timeout for the element be available to click

        :return: str, set rnd param status info
        """

        self.filter_rnb_debug_parameters(object_name=object_name, filter_param=filter_param, timeout=timeout)
        try:
            if self.element_exists(self.locator.DEBUG_DROPDOWN_BUTTON.format(filter_param), timeout=3):
                self.click_enabled_element(self.locator.DEBUG_DROPDOWN_BUTTON.format(filter_param), timeout)
                self.click_enabled_element(self.locator.DROPDOWN_VALUE_BUTTON.format(new_value), timeout)
            elif self.element_exists(self.locator.CHECKBOX_DEBUG_DROPDOWN_BUTTON.format(filter_param), timeout=3):
                new_value_list = ', '.join(new_value)
                for value in new_value_list.split(','):
                    time.sleep(1)
                    self.click_enabled_element(self.locator.CHECKBOX_DEBUG_DROPDOWN_BUTTON.format(filter_param),
                                               timeout)
                    self.click_enabled_element(self.locator.DROPDOWN_VALUE_BUTTON.format(value.strip()), timeout)
                    self.click_enabled_element(self.locator.FILTER_DROPDOWN_BUTTON, timeout)
            else:
                self.insert_text_to_enable_element(self.locator.INSERT_TEXT_VALUE, new_value, timeout)
        except Exception:
            raise RuntimeError("Element {} is not available to set the value. Please check".format(filter_param))
        time.sleep(1)
        return self.apply_rnd_debug_parameters(filter_param, timeout)
